theorem intervalSum_apply (D : ConstructionData 𝕜) {N : ℕ}
    (I : FiniteIntervalFamily N) (x : C00 𝕜) :
    intervalSum D I x = ∑ i, implicitNorm D (restrict (I.interval i) x)

